<?php
/** Server-neutral filesystem and protocol health facts. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Diagnostics;
use Nakhostin\PerformanceEngine\Environment\EnvironmentReport;
final class ServerHealthCheck { /** @var EnvironmentReport */ private $environment; public function __construct( EnvironmentReport $environment ) { $this->environment = $environment; } public function run(): array { $cache = defined( 'WP_CONTENT_DIR' ) ? WP_CONTENT_DIR . '/cache' : sys_get_temp_dir(); return array( 'server' => $this->environment->server(), 'http_protocol' => sanitize_text_field( (string) ( $_SERVER['SERVER_PROTOCOL'] ?? 'unknown' ) ), 'cache_path' => basename( $cache ), 'filesystem_writable' => is_dir( $cache ) ? is_writable( $cache ) : is_writable( dirname( $cache ) ), 'recommendation' => $this->recommendation() ); } private function recommendation(): string { $server = $this->environment->server(); if ( in_array( $server, array( 'litespeed', 'openlitespeed' ), true ) ) { return 'Prefer the available native LiteSpeed cache provider.'; } if ( 'nginx' === $server ) { return 'Use NPE Early Cache; FastCGI cache is an optional external server configuration.'; } if ( 'apache' === $server ) { return 'Use NPE Early Cache; server-level caching is optional.'; } return 'Use NPE Early Cache with its filesystem fallback.'; } }
